using System.Collections.Generic;using Janseon.Core;using Janseon.Core.Data;using Janseon.Data.Validation;
namespace Janseon.Data.Repositories { public sealed class StationCatalogRepository:IReadOnlyStationCatalog { readonly Dictionary<string,StationCatalogItem> byId=new Dictionary<string,StationCatalogItem>(System.StringComparer.Ordinal);readonly Dictionary<string,StationCatalogItem> byCore=new Dictionary<string,StationCatalogItem>(System.StringComparer.Ordinal);public IReadOnlyList<StationCatalogItem> All{get;}public StationCatalogRepository(GameDataCatalogIndex i){All=i.Stations;foreach(var x in All){byId.Add(x.StableId,x);byCore.Add(x.CoreStationId.Value,x);}}public bool TryGet(string id,out StationCatalogItem x)=>byId.TryGetValue(id??string.Empty,out x);public bool TryGetByCoreId(StationId id,out StationCatalogItem x)=>byCore.TryGetValue(id.Value??string.Empty,out x);}}
